import { expect, test } from '../fixtures';

/** A value that is new on every run (an email, a name), so a second run does not collide with the first. */
function makeUnique(): (base: string) => string {
  const seen = new Map<string, string>();
  return (base) => {
    const known = seen.get(base);
    if (known) return known;
    const tag = Math.random().toString(36).slice(2, 8);
    const at = base.indexOf('@');
    const value = at === -1 ? `${base}-${tag}` : `${base.slice(0, at)}+${tag}${base.slice(at)}`;
    seen.set(base, value);
    return value;
  };
}

// Starts from the admin session, not the default one.
test.use({ storageState: process.env.SOVA_AUTH_STATE_ADMIN! });

test('Admin add user taken', async ({ page }) => {
  const unique = makeUnique();

  await test.step('Open the add-user form', async () => {
    await page.goto('/admin/users/add');
  });

  await test.step('Type a taken username', async () => {
    await page.getByRole('textbox', { name: 'Username', exact: true }).fill('alice');
  });

  await test.step('Type a new email', async () => {
    await page.getByRole('textbox', { name: 'Email address', exact: true }).fill(unique('x@example.com'));
  });

  await test.step('Type a password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill('Pass-12345');
  });

  await test.step('Press Save', async () => {
    await page.getByRole('button', { name: 'Save', exact: true }).click();
  });

  await test.step('The error says the username is taken [code]', async () => {
    await expect(page.locator('.invalid-feedback')).toContainText('This username is already taken.');
  });
});
